def _contract_without(which):
    """기본 계약 (main 이 짓는 RealContract) 에서 정본 검사 하나를 끈 변이 클래스."""
    base = RR.RealContract

    class C(base):
        if which == 'ca':
            def ca_ext_record(self, man):
                return True, None
        else:
            def arm_problem(self, path, receipt):
                return None
    return C


