    def go():
        d, _rc, _so = led_new('AL18')
        _rc1, n1, _s1 = led_add(d, 'ladder:P1')
        return d, lad_att('AL18_P0', world('AL18'), d, n1, law='P0')
    d, a = scen('AL18', go)
