        f.mkdir(parents=True)
        a = dict({'schema': 'rint-r-attempt-v1', 'n': n1, 'target': 'ladder:P0', 'machine': MACH, 'resume_of': None,
                  'ledger_commit': git_(d, 'rev-parse', 'HEAD')}, **kw)
