    rows['fixture_keys'] = [pub == sorted(RR.ARM_PUBLIC), list(getattr(RR, 'ARM_FILE_ID_KEYS', ()))]
    if rows['fixture_keys'] != [True, ['file', 'index', 'sha256']]:
        bad['fixture_keys'] = rows['fixture_keys']
    for nm, prior, kinds, ok in rr3_variants():
        f = rr3_folder(f'C_{nm}')
