    rows['kind_callers'] = sorted(q for q, c in calls.items() if 'arms_read_kind' in c)
    want = {'shas_callers': ['arms_read_record'], 'projection_sites': ['arms_read_record'],
            'producers': {'Runner._execute': 2, 'ResumeRunner._copy': 2, 'MergeFetch.run': 2}, 'kind_callers': ['prior_runs_problem']}
