def rr3_cli_prep(arms_read, files):
    """앞 런 L01_floor (rc 0 · group_cause None · 요청 칸 · kit SBE) + 런 전 TIME_LIMIT (L02_ceiling) 요약 · 앞 런 폴더의 팔 파일 files {이름: 바이트}."""
    def p(f):
        for nm, raw in files.items():
            (Path(f) / 'L01_floor_arm1' / nm).write_bytes(raw)
        ct06_summ('TIME_LIMIT', [rr3_prior(arms_read)], run=RR3_L2)(f)
    return p


